import React, { useState } from 'react';
import { List, ListItem, ListItemText, IconButton, TextField, Button, Box } from '@mui/material';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';

const TaskList = ({ tasks, onMarkAsCompleted, onUpdateTask, onDeleteTask }) => {
  const [editingId, setEditingId] = useState(null);
  const [editedTask, setEditedTask] = useState({});

  const handleEdit = (task) => {
    setEditingId(task.id);
    setEditedTask({ name: task.name, description: task.description });
  };

  const handleSave = (id) => {
    onUpdateTask(id, editedTask);
    setEditingId(null);
  };

  return (
    <List>
      {tasks.map((task) => (
        <ListItem key={task.id} sx={{ display: 'flex', alignItems: 'center' }}>
          {editingId === task.id ? (
            <Box sx={{ width: '100%' }}>
              <TextField
                label="Task Name"
                value={editedTask.name}
                onChange={(e) => setEditedTask({ ...editedTask, name: e.target.value })}
                fullWidth
                margin="normal"
              />
              <TextField
                label="Task Description"
                value={editedTask.description}
                onChange={(e) => setEditedTask({ ...editedTask, description: e.target.value })}
                fullWidth
                margin="normal"
                multiline
                rows={2}
              />
              <Button variant="contained" color="primary" onClick={() => handleSave(task.id)}>
                Save
              </Button>
            </Box>
          ) : (
            <>
              <ListItemText primary={task.name} secondary={task.description} />
              <IconButton edge="end" onClick={() => handleEdit(task)}>
                <EditIcon color="primary" />
              </IconButton>
              <IconButton edge="end" onClick={() => onMarkAsCompleted(task.id)}>
                <CheckCircleIcon color="success" />
              </IconButton>
              <IconButton edge="end" onClick={() => onDeleteTask(task.id)}>
                <DeleteIcon color="error" />
              </IconButton>
            </>
          )}
        </ListItem>
      ))}
    </List>
  );
};

export default TaskList;
